    private Constants() {
    }
}

/**
 * MAIN: the menu loop. The only Scanner of the program lives here; each option reads and
 * validates its own input, then calls the controller ONCE (Part 12).
 */
public final class Main {

    // Private constructor: Main only has static methods (check sheet 3.4).
    private Main() {
    }

    // Shows the menu until the user chooses Exit.
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        boolean running = true;
        String choice = "";

        // show the menu again after every option, until Exit is chosen
        while (running) {
            System.out.println(Message.MENU);
            System.out.print(Message.INPUT_CHOICE);
            choice = sc.nextLine().trim();

            // one case per option: its form, then ONE call to the controller
            switch (choice) {
                // option 1, in the assignment: controller.addDoctor(inputAdd(sc));
                case Constants.MENU_ADD:
                    System.out.println(Message.TITLE_ADD);
                    break;

                // option 2, in the assignment: controller.updateDoctor(inputUpdate(sc));
                case Constants.MENU_UPDATE:
                    System.out.println(Message.TITLE_UPDATE);
                    break;

                // option 3, in the assignment: controller.deleteDoctor(inputDelete(sc));
                case Constants.MENU_DELETE:
                    System.out.println(Message.TITLE_DELETE);
                    break;

                // option 4, in the assignment: controller.searchDoctor(inputSearch(sc));
                case Constants.MENU_SEARCH:
                    System.out.println(Message.TITLE_SEARCH);
                    break;

                // option 5, in the assignment: controller.displayDoctors();
                case Constants.MENU_DISPLAY:
                    System.out.println(Message.TITLE_DISPLAY);
                    break;

                // option 6: leave the loop - no System.exit, so a final save can still run
                case Constants.MENU_EXIT:
                    running = false;
                    System.out.println(Message.GOODBYE);
                    break;

                // anything else: a letter, an empty Enter, a number out of range
                default:
                    System.out.println(Message.INVALID_CHOICE);
                    break;
            }
        }
    }
