package utils;

import constants.Constants;
import constants.Message;

/**
 * Shared checks of what the user typed: public final class, private constructor, static
 * methods only. No Scanner, no print - each method takes the String main read and either
 * returns the value or throws Exception(Message.X) for main to print.
 */
public final class Validation {

    // Private constructor: every method is called through the class name (check sheet 3.4).
    private Validation() {
    }

    // Returns the trimmed text when it is not empty.
    public static String getNonEmpty(String input) throws Exception {
        String text = input.trim();

        // an empty line is refused so main can ask again
        if (text.isEmpty()) {
            throw new Exception(Message.REQUIRED);
        }

        return text;
    }

    // Converts an int and checks it lies in [min, max]; letters, empty input and
    // out-of-range numbers are refused.
    public static int getInt(String input, int min, int max) throws Exception {
        int value = 0;

        // parse first, so a letter gives the "digit" message
        try {
            value = Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // letters, "3.5" or an empty line: not a whole number
            throw new Exception(Message.NOT_DIGIT);
        }

        // then the range - each comparison in its own brackets (check sheet 3.3)
        if ((value < min) || (value > max)) {
            throw new Exception(String.format(Message.OUT_OF_RANGE, min, max));
        }

        return value;
    }

    // Converts a double that must be strictly greater than zero - salary, price, area.
    public static double getPositiveDouble(String input) throws Exception {
        double value = 0;

        // parse first, so a letter gives the "digit" message
        try {
            value = Double.parseDouble(input.trim());
        } catch (NumberFormatException e) {
            // letters or an empty line: not a number
            throw new Exception(Message.NOT_DIGIT);
        }

        // zero or negative: a number, but not a legal value
        if (value <= 0) {
            throw new Exception(Message.NOT_POSITIVE);
        }

        return value;
    }

    // Returns the text when it matches a pattern - ids, phone numbers; error is the
    // Message constant to throw otherwise.
    public static String getPattern(String input, String regex, String error)
            throws Exception {
        String text = getNonEmpty(input);

        // the WHOLE text must match, not just a part of it
        if (!text.matches(regex)) {
            throw new Exception(error);
        }

        return text;
    }

    // Converts a Y/N answer: true for Y, false for N, upper or lower case (check sheet 3.5).
    public static boolean getYesNo(String input) throws Exception {
        String answer = getNonEmpty(input);

        // Y or y means yes
        if (answer.equalsIgnoreCase(Constants.YES)) {
            return true;
        }

        // N or n means no
        if (answer.equalsIgnoreCase(Constants.NO)) {
            return false;
        }

        throw new Exception(Message.NOT_YES_NO);
    }
}

