// Asks for the salary until Validation accepts the line.
private static double inputSalary(Scanner sc) {
    String line = "";

    // keep asking until the line is a legal salary
    while (true) {
        System.out.print(Message.INPUT_SALARY);
        line = sc.nextLine();

        // a refused line prints the reason and loops again
        try {
            return Validation.getPositiveDouble(line);
        } catch (Exception e) {
            // "You must input a digit." or "Value must be greater than zero."
            System.out.println(e.getMessage());
        }
    }
}

