List<Integer> numberList = new ArrayList<>(Arrays.asList(1, 2, 2, 3));
List<Integer> forwardList = new ArrayList<>(Arrays.asList(1, 2, 2, 3));
List<Integer> backwardList = new ArrayList<>(Arrays.asList(1, 2, 2, 3));

// BROKEN 1 - throws ConcurrentModificationException
// for (Integer number : numberList) { if (number == 2) { numberList.remove(number); } }

// BROKEN 2 - a forwards index loop skips the second 2, leaves [1, 2, 3]
for (int i = 0; i < forwardList.size(); i++) {
    // remove(i) shifts every later element one place to the left
    if (forwardList.get(i) == 2) {
        forwardList.remove(i);
    }
}

System.out.println(forwardList);

// CORRECT - walk backwards, so removing never moves an unvisited element
for (int i = backwardList.size() - 1; i >= 0; i--) {
    // the elements that shift were already visited
    if (backwardList.get(i) == 2) {
        backwardList.remove(i);
    }
}

System.out.println(backwardList);

// ALSO CORRECT - removeIf says the intent in one line
System.out.println(numberList);
numberList.removeIf(number -> number == 2);
System.out.println(numberList);

