final class Validation {

    // Private constructor: every method is called through the class name.
    private Validation() {
    }

    // Converts a GPA and checks it lies in [0, 4].
    public static double getGpa(String input) throws Exception {
        double gpa = 0;

        // letters are not a GPA
        try {
            gpa = Double.parseDouble(input.trim());
        } catch (NumberFormatException e) {
            // the line is not a number at all
            throw new Exception(Message.NOT_DIGIT);
        }

        // each comparison in its own brackets (check sheet 3.3)
        if ((gpa < Constants.MIN_GPA) || (gpa > Constants.MAX_GPA)) {
            throw new Exception(Message.INVALID_GPA);
        }

        return gpa;
    }
}

