final class Constants {

    // Health of every new bee, in percent.
    public static final double FULL_HEALTH = 100;

    // Damage and health are percentages of this.
    public static final double PERCENT_BASE = 100.0;

    // Smallest legal damage, in percent.
    public static final int MIN_PERCENT = 0;

    // Largest legal damage, in percent.
    public static final int MAX_PERCENT = 100;

    // A worker below 70% health is dead.
    public static final int WORKER_THRESHOLD = 70;

    // A queen below 20% health is dead.
    public static final int QUEEN_THRESHOLD = 20;

    // A drone below 50% health is dead.
    public static final int DRONE_THRESHOLD = 50;

    // One line of the demo report: kind, health, dead or alive.
    public static final String BEE_FORMAT = "%-7s health=%5.1f dead=%b%n";

    // Private constructor: this class only holds constants.
    private Constants() {
    }
}

/**
 * constants/Message.java in a real project.
 */
final class Message {

    // The damage is outside [0, 100]; the two %d are the bounds.
    public static final String INVALID_DAMAGE = "percent must be between %d and %d";

    // Name of a worker bee.
    public static final String WORKER = "Worker";

    // Name of a queen bee.
    public static final String QUEEN = "Queen";

    // Name of a drone.
    public static final String DRONE = "Drone";

    // Private constructor: this class only holds constants.
    private Message() {
    }
}

/**
 * MODEL: every bee, and the rule that is the same for every bee.
 */
public abstract class Bee {

    // Health in percent; private, so nothing outside can assign to it.
    private double health = Constants.FULL_HEALTH;

    // Read-only view. There is deliberately NO setHealth.
    public double getHealth() {
        return health;
    }

    // Each kind of bee decides the health below which it is dead.
    protected abstract int getThreshold();

    // True as soon as the health falls below this kind's threshold.
    public boolean isDead() {
        return health < getThreshold();
    }

    // The only way health can ever change: minus percent% of the CURRENT health.
    // brief: Damage(int percent)
    public void damage(int percent) {
        // the brief: a dead bee records no further damage
        if (isDead()) {
            return;
        }

        // the brief: the parameter is between 0 and 100
        if ((percent < Constants.MIN_PERCENT) || (percent > Constants.MAX_PERCENT)) {
            throw new IllegalArgumentException(String.format(Message.INVALID_DAMAGE,
                    Constants.MIN_PERCENT, Constants.MAX_PERCENT));
        }

        health = health - ((health * percent) / Constants.PERCENT_BASE);
    }
}

