/**
 * MODEL: every shape has an area and a name, without saying how.
 */
abstract class Shape {

    // The area; each concrete shape has its own formula.
    public abstract double getArea();

    // The name shown on screen.
    public abstract String getName();
}

/**
 * MODEL: the flat shapes.
 */
abstract class TwoDimensionalShape extends Shape {
}

/**
 * MODEL: the solid shapes, which also have a volume.
 */
abstract class ThreeDimensionalShape extends Shape {

    // The volume; each concrete solid has its own formula.
    public abstract double getVolume();
}

/**
 * MODEL: a circle.
 */
class Circle extends TwoDimensionalShape {

    // Radius of the circle.
    private double radius;

    // Creates a circle of the given radius.
    public Circle(double radius) {
        this.radius = radius;
    }

    // Area of a circle: pi times radius squared.
    @Override
    public double getArea() {
        return Math.PI * radius * radius;
    }

    // The name shown on screen.
    @Override
    public String getName() {
        return Message.CIRCLE;
    }
}

/**
 * MODEL: a cube.
 */
class Cube extends ThreeDimensionalShape {

    // Length of one edge.
    private double side;

    // Creates a cube of the given edge.
    public Cube(double side) {
        this.side = side;
    }

    // Surface area: six square faces.
    @Override
    public double getArea() {
        return Constants.CUBE_FACES * (side * side);
    }

    // Volume: edge cubed.
    @Override
    public double getVolume() {
        return side * side * side;
    }

    // The name shown on screen.
    @Override
    public String getName() {
        return Message.CUBE;
    }
}

