/**
 * MODEL: one doctor. toString gives its table row; equals and hashCode say that two
 * doctors are the same doctor when the code matches.
 */
class Doctor {

    // Unique code of the doctor.
    private String code;

    // Full name of the doctor.
    private String name;

    // Creates a doctor with both fields filled in.
    public Doctor(String code, String name) {
        this.code = code;
        this.name = name;
    }

    // Returns the doctor code.
    public String getCode() {
        return code;
    }

    // Returns the doctor name.
    public String getName() {
        return name;
    }

    // One table row - without this you get Doctor@1b6d3586.
    @Override
    public String toString() {
        return String.format(Constants.ROW_FORMAT, code, name);
    }

    // Two doctors are the same doctor when the code matches.
    @Override
    public boolean equals(Object other) {
        // the very same object
        if (this == other) {
            return true;
        }

        // null, or not a doctor at all
        if (!(other instanceof Doctor)) {
            return false;
        }

        return code.equals(((Doctor) other).getCode());
    }

    // ALWAYS overridden together with equals: equal doctors give equal hash codes.
    @Override
    public int hashCode() {
        return code.hashCode();
    }
}

