import java.util.Arrays;

/**
 * Bubble sort on its own, to run and trace. In a submission the method body becomes a
 * private method of the service (SortService.sortByBubble in P0001).
 */
public final class BubbleSort {

    // Private constructor: only static methods here (check sheet 3.4).
    private BubbleSort() {
    }

    // Sorts ascending, in place: swaps neighbours that are in the wrong order; a pass
    // without any swap ends the sort.
    public static void sortByBubble(int[] numberArray) {
        int temp = 0;

        // pass i parks the biggest remaining number at position length - 1 - i
        for (int i = 0; i < (numberArray.length - 1); i++) {
            boolean swapped = false;

            // after i passes the last i numbers are already in place
            for (int j = 0; j < (numberArray.length - 1 - i); j++) {
                // wrong order: the bigger number moves one step right
                if (numberArray[j] > numberArray[j + 1]) {
                    temp = numberArray[j];
                    numberArray[j] = numberArray[j + 1];
                    numberArray[j + 1] = temp;
                    swapped = true;
                }
            }

            // no swap in a whole pass: the array is already sorted - stop early
            if (!swapped) {
                return;
            }
        }
    }

    // Demo only: sorts two arrays and prints them (in a submission the View prints).
    public static void main(String[] args) {
        int[] numberArray = {5, 1, 12, -5, 16};
        int[] sortedArray = {1, 2, 3, 4, 5};

        sortByBubble(numberArray);
        System.out.println(Arrays.toString(numberArray));

        // already sorted: one pass, no swap, returns at once
        sortByBubble(sortedArray);
        System.out.println(Arrays.toString(sortedArray));
    }
}

