import java.util.Arrays;

/**
 * Bubble sort đứng riêng để chạy thử và lần từng bước. Trong bài nộp, thân hàm này thành
 * một hàm private của service (SortService.sortByBubble ở P0001).
 */
public final class BubbleSort {

    // Constructor private: lớp này chỉ có hàm static (tờ checklist 3.4).
    private BubbleSort() {
    }

    // Sắp tăng dần, tại chỗ: đổi chỗ hai phần tử kề nhau khi sai thứ tự; một lượt không
    // đổi chỗ nào thì dừng.
    public static void sortByBubble(int[] numberArray) {
        int temp = 0;

        // lượt i đưa số lớn nhất còn lại về vị trí length - 1 - i
        for (int i = 0; i < (numberArray.length - 1); i++) {
            boolean swapped = false;

            // sau i lượt thì i phần tử cuối đã đúng chỗ -> không duyệt lại
            for (int j = 0; j < (numberArray.length - 1 - i); j++) {
                // sai thứ tự: số lớn hơn lùi sang phải một bước
                if (numberArray[j] > numberArray[j + 1]) {
                    temp = numberArray[j];
                    numberArray[j] = numberArray[j + 1];
                    numberArray[j + 1] = temp;
                    swapped = true;
                }
            }

            // cả lượt không đổi chỗ nào -> mảng đã sắp xong, dừng sớm
            if (!swapped) {
                return;
            }
        }
    }

    // Chỉ để demo: sắp hai mảng rồi in ra (trong bài nộp thì View in).
    public static void main(String[] args) {
        int[] numberArray = {5, 1, 12, -5, 16};
        int[] sortedArray = {1, 2, 3, 4, 5};

        sortByBubble(numberArray);
        System.out.println(Arrays.toString(numberArray));

        // mảng đã sắp sẵn: chỉ 1 lượt, không đổi chỗ, thoát luôn
        sortByBubble(sortedArray);
        System.out.println(Arrays.toString(sortedArray));
    }
}

