/**
 * Binary search on its own. In a submission it is a private method of the service, and
 * the repository holds the sorted array.
 */
public final class BinarySearch {

    // Private constructor: only static methods here.
    private BinarySearch() {
    }

    // Returns the index of key, or -1 when it is absent. The array MUST be sorted.
    public static int searchBinary(int[] numberArray, int key) {
        int low = 0;
        int high = numberArray.length - 1;
        int middle = 0;

        // each step keeps only the half that can still hold the key
        while (low <= high) {
            middle = low + ((high - low) / 2);    // avoids overflow on huge arrays

            // found it, or throw away the half that cannot hold it
            if (numberArray[middle] == key) {
                return middle;
            } else if (numberArray[middle] < key) {
                low = middle + 1;                  // discard the left half
            } else {
                high = middle - 1;                 // discard the right half
            }
        }

        return -1;
    }

    // Demo only: two searches on a sorted array, one on an unsorted one.
    public static void main(String[] args) {
        int[] sortedArray = {-1, 5, 6, 18, 19, 25, 46, 78, 102, 114};
        int[] unsortedArray = {5, 1, 12};

        System.out.println(searchBinary(sortedArray, 6));       // 2
        System.out.println(searchBinary(sortedArray, 103));     // -1

        // 5 IS there - and binary search still reports -1
        System.out.println(searchBinary(unsortedArray, 5));
    }
}

/**
 * Fibonacci two ways, on its own. In a submission the chosen method is a private method of
 * the service (P0009), and the View prints the result.
 */
public final class Fibonacci {

    // Private constructor: only static methods here.
    private Fibonacci() {
    }

    // Recursive: matches the definition, but recomputes the same values endlessly.
    public static long calculateFibonacciRecursive(int position) {
        // base case: fib(0) = 0, fib(1) = 1
        if (position <= 1) {
            return position;
        }

        return calculateFibonacciRecursive(position - 1)
                + calculateFibonacciRecursive(position - 2);
    }

    // Iterative: one pass, O(n). Use this in the assignment.
    public static long calculateFibonacciIterative(int position) {
        long previous = 0;
        long current = 1;
        long next = 0;

        // each step moves the pair one place along the sequence
        for (int i = 0; i < position; i++) {
            next = previous + current;
            previous = current;
            current = next;
        }

        return previous;
    }

    // Demo only: the same answer both ways, at a very different cost.
    public static void main(String[] args) {
        long startTime = 0;
        long recursiveMs = 0;
        long iterativeMs = 0;

        System.out.println(calculateFibonacciRecursive(20) + " "
                + calculateFibonacciIterative(20));

        // time the recursive version
        startTime = System.nanoTime();
        calculateFibonacciRecursive(32);
        recursiveMs = (System.nanoTime() - startTime) / 1_000_000;

        // time the iterative version
        startTime = System.nanoTime();
        calculateFibonacciIterative(32);
        iterativeMs = (System.nanoTime() - startTime) / 1_000_000;

        System.out.println("recursive took longer: " + (recursiveMs > iterativeMs));
        System.out.println("fib(90) = " + calculateFibonacciIterative(90));
    }
}

/**
 * Base conversion on its own (P0011). In a submission it is a private method of the
 * service; the View prints the result.
 */
public final class BaseConverter {

    // Private constructor: only static methods here.
    private BaseConverter() {
    }

    // Decimal to any base from 2 to 16, the algorithm the brief wants you to show.
    public static String convertToBase(int value, int base) {
        String digitText = "0123456789ABCDEF";
        StringBuilder resultBuilder = new StringBuilder();
        int remaining = value;

        // zero has no remainder to collect
        if (remaining == 0) {
            return "0";
        }

        // each remainder is the next digit, collected from right to left
        while (remaining > 0) {
            resultBuilder.insert(0, digitText.charAt(remaining % base));
            remaining = remaining / base;                 // integer division
        }

        return resultBuilder.toString();
    }

    // Demo only: by hand, then the library equivalents to check the answer.
    public static void main(String[] args) {
        System.out.println(convertToBase(255, 2));        // 11111111
        System.out.println(convertToBase(255, 16));       // FF

        // the library equivalents, for checking your own answer
        System.out.println(Integer.toBinaryString(255));
        System.out.println(Integer.toHexString(255).toUpperCase());
        System.out.println(Integer.parseInt("FF", 16));
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Selection sort and insertion sort on their own (P0002, P0003). Neither prints: selection
 * returns the array after every pass, so the caller - in a submission, the View through
 * the ResponseDTO - decides how to show the trace.
 */
public final class TwoSorts {

    // Private constructor: only static methods here.
    private TwoSorts() {
    }

    // Selection: find the minimum in the unsorted tail, swap it to the front. Returns the
    // array as text after each pass.
    public static List<String> sortBySelection(int[] numberArray) {
        List<String> passList = new ArrayList<>();
        int minIndex = 0;
        int temp = 0;

        // pass i puts the smallest remaining number at position i
        for (int i = 0; i < (numberArray.length - 1); i++) {
            minIndex = i;

            // look for the smallest number in the unsorted tail
            for (int j = i + 1; j < numberArray.length; j++) {
                // a smaller number becomes the new minimum
                if (numberArray[j] < numberArray[minIndex]) {
                    minIndex = j;
                }
            }

            // one swap per pass, at most
            if (minIndex != i) {
                temp = numberArray[i];
                numberArray[i] = numberArray[minIndex];
                numberArray[minIndex] = temp;
            }

            passList.add(Arrays.toString(numberArray));
        }

        return passList;
    }

    // Insertion: hold numberArray[i], shift bigger numbers right, drop it in the gap.
    public static void sortByInsertion(int[] numberArray) {
        int key = 0;
        int j = 0;

        // everything left of i is already sorted
        for (int i = 1; i < numberArray.length; i++) {
            key = numberArray[i];
            j = i - 1;

            // shift, do not swap - each comparison in its own brackets
            while ((j >= 0) && (numberArray[j] > key)) {
                numberArray[j + 1] = numberArray[j];
                j--;
            }

            numberArray[j + 1] = key;
        }
    }

    // Demo only: prints the selection trace, then the insertion result.
    public static void main(String[] args) {
        int[] selectionArray = {5, 1, 12, -5, 16};
        int[] insertionArray = {7, -5, 2, 16, 4};
        List<String> passList = sortBySelection(selectionArray);

        // the trace comes back as data; printing it is the caller's job
        for (int i = 0; i < passList.size(); i++) {
            System.out.println("pass " + (i + 1) + ": " + passList.get(i));
        }

        sortByInsertion(insertionArray);
        System.out.println("insertion: " + Arrays.toString(insertionArray));
    }
}

import java.util.Arrays;

/**
 * Quicksort and merge sort on their own (P0004, P0005). In a submission each is a private
 * method of the service; nothing here prints except the demo main.
 */
public final class FastSorts {

    // Private constructor: only static methods here.
    private FastSorts() {
    }

    // QUICKSORT: sorts numberArray[low..high] in place.
    public static void sortByQuick(int[] numberArray, int low, int high) {
        int pivotIndex = 0;

        // base case: zero or one number is already sorted
        if (low >= high) {
            return;
        }

        pivotIndex = splitAroundPivot(numberArray, low, high);
        sortByQuick(numberArray, low, pivotIndex - 1);
        sortByQuick(numberArray, pivotIndex + 1, high);
    }

    // The partition step: puts the pivot (the last number) at its final place, smaller
    // numbers on its left, and returns that place.
    private static int splitAroundPivot(int[] numberArray, int low, int high) {
        int pivot = numberArray[high];
        int i = low - 1;
        int temp = 0;

        // every number not bigger than the pivot moves to the left part
        for (int j = low; j < high; j++) {
            // this number belongs on the left of the pivot
            if (numberArray[j] <= pivot) {
                i++;
                temp = numberArray[i];
                numberArray[i] = numberArray[j];
                numberArray[j] = temp;
            }
        }

        // the pivot goes right after the left part: its final resting place
        temp = numberArray[i + 1];
        numberArray[i + 1] = numberArray[high];
        numberArray[high] = temp;
        return i + 1;
    }

    // MERGE SORT: sorts numberArray[left..right].
    public static void sortByMerge(int[] numberArray, int left, int right) {
        int middle = 0;

        // base case: zero or one number is already sorted
        if (left >= right) {
            return;
        }

        middle = (left + right) / 2;
        sortByMerge(numberArray, left, middle);
        sortByMerge(numberArray, middle + 1, right);
        mergeHalves(numberArray, left, middle, right);
    }

    // Merges the sorted halves [left..middle] and [middle + 1..right].
    private static void mergeHalves(int[] numberArray, int left, int middle, int right) {
        int[] tempArray = new int[right - left + 1];
        int i = left;
        int j = middle + 1;
        int k = 0;

        // take the smaller head of the two halves each time
        while ((i <= middle) && (j <= right)) {
            // the left head is not bigger: it goes first, which keeps the sort stable
            if (numberArray[i] <= numberArray[j]) {
                tempArray[k] = numberArray[i];
                i++;
            } else {
                tempArray[k] = numberArray[j];
                j++;
            }

            k++;
        }

        // leftovers on the left
        while (i <= middle) {
            tempArray[k] = numberArray[i];
            i++;
            k++;
        }

        // leftovers on the right
        while (j <= right) {
            tempArray[k] = numberArray[j];
            j++;
            k++;
        }

        System.arraycopy(tempArray, 0, numberArray, left, tempArray.length);
    }

    // Demo only: sorts the same numbers both ways.
    public static void main(String[] args) {
        int[] quickArray = {5, 1, 12, -5, 16, 2};
        int[] mergeArray = {5, 1, 12, -5, 16, 2};

        sortByQuick(quickArray, 0, quickArray.length - 1);
        System.out.println("quick: " + Arrays.toString(quickArray));

        sortByMerge(mergeArray, 0, mergeArray.length - 1);
        System.out.println("merge: " + Arrays.toString(mergeArray));
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Linear search, two shapes, on their own. In a submission the exact search is a method of
 * the repository (find by id) and the search by part of a name a method of the service.
 */
public final class LinearSearch {

    // Private constructor: only static methods here.
    private LinearSearch() {
    }

    // Exact match on an int array - returns the index of the FIRST hit, or -1.
    public static int findIndex(int[] numberArray, int key) {
        // check every element, left to right
        for (int i = 0; i < numberArray.length; i++) {
            // stop at the first hit
            if (numberArray[i] == key) {
                return i;
            }
        }

        return -1;
    }

    // Partial, case-insensitive match - what the CRUD briefs actually ask for.
    public static List<String> searchByPart(List<String> nameList, String part) {
        List<String> foundList = new ArrayList<>();
        String needle = part.toLowerCase();

        // keep every name that contains the text, whatever the case
        for (String name : nameList) {
            // a match anywhere in the name
            if (name.toLowerCase().contains(needle)) {
                foundList.add(name);
            }
        }

        return foundList;
    }

    // Demo only: two exact searches, two partial ones.
    public static void main(String[] args) {
        int[] numberArray = {4, 8, 15, 16};
        List<String> nameList = Arrays.asList("Tran Binh", "Le Hoa", "Nguyen Le Minh");

        System.out.println(findIndex(numberArray, 15));
        System.out.println(findIndex(numberArray, 99));
        System.out.println(searchByPart(nameList, "le"));
        System.out.println(searchByPart(nameList, "zz"));
    }
}

