/**
 * utils/FileUtils.java in a real project: the raw part of reading and writing a text file.
 * It knows nothing about doctors, so it is copied unchanged from one assignment to the next.
 */
final class FileUtils {

    // Private constructor: every method is called through the class name.
    private FileUtils() {
    }

    // Tells whether the file is already on the disk (the first run has none).
    public static boolean isFileExist(String fileName) {
        File file = new File(fileName);

        return file.exists() && file.isFile();
    }

    // Reads every line of a text file.
    public static ArrayList<String> readLines(String fileName) throws Exception {
        ArrayList<String> lineList = new ArrayList<>();

        // try-with-resources: the reader is closed even when a read fails
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
                new FileInputStream(fileName), StandardCharsets.UTF_8))) {
            String line = reader.readLine();

            // readLine() returns null at the end of the file
            while (line != null) {
                lineList.add(line);
                line = reader.readLine();
            }
        } catch (IOException e) {
            // missing, locked, no permission...
            throw new Exception(String.format(Message.CANNOT_READ, fileName));
        }

        return lineList;
    }

    // Replaces the whole file with the given lines.
    public static void writeLines(String fileName, ArrayList<String> lineList)
            throws Exception {
        // try-with-resources: the writer is flushed and closed even on failure
        try (BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(
                new FileOutputStream(fileName), StandardCharsets.UTF_8))) {
            // one element of the list = one line of the file
            for (String line : lineList) {
                writer.write(line);
                writer.newLine();
            }
        } catch (IOException e) {
            // read-only file, full disk...
            throw new Exception(String.format(Message.CANNOT_WRITE, fileName));
        }
    }
}

