// repository/AssetRepository.java - the format: one line becomes one object
public void loadData(ArrayList<String> lineList) {
    String[] partArray = null;

    // start again from an empty store
    assetList.clear();

    // one line = one asset
    for (String line : lineList) {
        partArray = line.split(Constants.DATA_SEPARATOR);

        // a blank line or a wrong number of columns is not an asset
        if (partArray.length != Constants.ASSET_COLUMNS) {
            continue;
        }

        // a number that is not a number costs this line only
        try {
            assetList.add(parse(partArray));
        } catch (NumberFormatException e) {
            // skip the damaged line
            continue;
        }
    }
}

// Six columns: id, name, color, price, weight, quantity (column numbers in Constants).
private Asset parse(String[] partArray) {
    return new Asset(partArray[Constants.ASSET_ID].trim(),
            partArray[Constants.ASSET_NAME].trim(),
            partArray[Constants.ASSET_COLOR].trim(),
            Double.parseDouble(partArray[Constants.ASSET_PRICE].trim()),
            Double.parseDouble(partArray[Constants.ASSET_WEIGHT].trim()),
            Integer.parseInt(partArray[Constants.ASSET_QUANTITY].trim()));
}

