    // The "database": doctors in the order they were added.
    private ArrayList<Doctor> doctorList;

    // Creates an empty repository.
    public DoctorRepository() {
        doctorList = new ArrayList<>();
    }

    // Stores a new doctor built from the request (a DTO may be passed on whole).
    public void addDoctor(DoctorRequestDTO requestDTO) {
        doctorList.add(new Doctor(requestDTO.getCode(), requestDTO.getName(),
                requestDTO.getSpecialization()));
    }

    // Finds a doctor by code, ignoring case; null when nobody has it.
    public Doctor findByCode(String code) {
        // look at every doctor once
        for (Doctor doctor : doctorList) {
            // same code, whatever the case
            if (doctor.getCode().equalsIgnoreCase(code)) {
                return doctor;
            }
        }

        return null;
    }

    // Returns a copy of the list, so a caller can never add or remove stored doctors.
    public ArrayList<Doctor> findAll() {
        return new ArrayList<>(doctorList);
    }
}

