package service;

import constants.Message;
import dto.DoctorRequestDTO;
import dto.DoctorResponseDTO;
import java.util.ArrayList;
import model.Doctor;
import repository.DoctorRepository;

/**
 * SERVICE: the rules beyond simple CRUD - the duplicate check and the search. Called only
 * by the controller; no print, no keyboard, no view.
 */
public class DoctorService {

    // Where the doctors are kept (Service -> Repository -> Model).
    private DoctorRepository doctorRepository;

    // Creates the service with an empty repository.
    public DoctorService() {
        doctorRepository = new DoctorRepository();
    }

    // Adds a doctor unless the code is already used; the answer carries the success line.
    public DoctorResponseDTO addDoctor(DoctorRequestDTO requestDTO) throws Exception {
        DoctorResponseDTO responseDTO = new DoctorResponseDTO();

        // the brief: a code may appear only once
        if (doctorRepository.findByCode(requestDTO.getCode()) != null) {
            throw new Exception(String.format(Message.DUPLICATE_CODE, requestDTO.getCode()));
        }

        doctorRepository.addDoctor(requestDTO);
        responseDTO.setMessage(String.format(Message.ADD_SUCCESS, requestDTO.getCode()));
        return responseDTO;
    }

    // Finds the doctors whose name contains the text, ignoring case; the answer carries
    // their rows (an empty list when nobody matched).
    public DoctorResponseDTO searchByName(DoctorRequestDTO requestDTO) {
        DoctorResponseDTO responseDTO = new DoctorResponseDTO();
        ArrayList<String> rowList = new ArrayList<>();
        String text = requestDTO.getSearchText().toLowerCase();

        // a linear scan: "contains" cannot be done by binary search
        for (Doctor doctor : doctorRepository.findAll()) {
            // keep the doctor when the name contains the text
            if (doctor.getName().toLowerCase().contains(text)) {
                rowList.add(doctor.toString());
            }
        }

        responseDTO.setRowList(rowList);
        return responseDTO;
    }
}

