        doctorService = new DoctorService();
        doctorView = new DoctorView();
    }

    // Option 1: adds a doctor, then the view prints the result - once. A duplicate code
    // arrives as Exception(Message.X), which main prints.
    public void addDoctor(DoctorRequestDTO requestDTO) throws Exception {
        DoctorResponseDTO responseDTO = doctorService.addDoctor(requestDTO);

        // hand the answer to the view, then render it - once for the whole flow
        doctorView.setResponseDTO(responseDTO);
        doctorView.display();
    }

    // Option 2: finds doctors by part of the name, then the view prints them - once.
    public void searchDoctor(DoctorRequestDTO requestDTO) {
        DoctorResponseDTO responseDTO = doctorService.searchByName(requestDTO);

        // hand the answer to the view, then render it - once for the whole flow
        doctorView.setResponseDTO(responseDTO);
        doctorView.display();
    }
}

