package view;

import constants.Message;
import dto.DoctorResponseDTO;

/**
 * VIEW: prints the answer of one menu option. It receives the data through its attribute
 * (the ResponseDTO, as in the lecturer's sample), never through the parameters of display().
 */
public class DoctorView {

    // The answer to print, handed over by the controller.
    private DoctorResponseDTO responseDTO;

    // Receives the answer the next display() will print.
    public void setResponseDTO(DoctorResponseDTO responseDTO) {
        this.responseDTO = responseDTO;
    }

    // Prints what the controller set: a one-line result, or the rows of a search.
    public void display() {
        // an add answers with one line
        if (responseDTO.getMessage() != null) {
            System.out.println(responseDTO.getMessage());
        }

        // a search answers with its rows
        if (responseDTO.getRowList() != null) {
            displayRows();
        }
    }

    // Prints "No doctor found." or one line per doctor.
    private void displayRows() {
        // nobody matched the search text
        if (responseDTO.getRowList().isEmpty()) {
            System.out.println(Message.NOT_FOUND);
        }

        // one line per doctor; Doctor.toString() already padded it
        for (String row : responseDTO.getRowList()) {
            System.out.println(row);
        }
    }
}

