package utils;

import constants.Message;

/**
 * Shared checks of what the user typed: public final class, private constructor, static
 * methods. No Scanner, no print - it returns the value or throws Exception(Message.X).
 */
public final class Validation {

    // Private constructor: every method is called through the class name.
    private Validation() {
    }

    // Returns the trimmed text when it is not empty.
    public static String getNonEmpty(String input) throws Exception {
        String text = input.trim();

        // an empty line is refused so main can ask again
        if (text.isEmpty()) {
            throw new Exception(Message.REQUIRED);
        }

        return text;
    }

    // Converts a menu choice and checks it lies in [min, max].
    public static int getChoice(String input, int min, int max) throws Exception {
        int choice = 0;

        // parse first, so a letter gives the "digit" message
        try {
            choice = Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // letters or an empty line: not a number at all
            throw new Exception(Message.INVALID_NUMBER);
        }

        // then the range, each comparison in its own brackets
        if ((choice < min) || (choice > max)) {
            throw new Exception(String.format(Message.INVALID_RANGE, min, max));
        }

        return choice;
    }
}

