package main;

import constants.Constants;
import constants.Message;
import controller.DoctorController;
import dto.DoctorRequestDTO;
import java.util.Scanner;
import utils.Validation;

/**
 * MAIN: the work flow - the menu, the only Scanner, every prompt and every validation.
 * Each menu option builds a RequestDTO and calls the controller ONCE; an Exception thrown
 * below is printed here.
 */
public final class Main {

    // Private constructor: Main only has static methods (check sheet 3.4).
    private Main() {
    }

    // Shows the menu until the user chooses Exit.
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        DoctorController controller = new DoctorController();
        DoctorRequestDTO requestDTO = null;
        boolean running = true;
        int choice = 0;

        // show the menu again after every option, until Exit is chosen
        while (running) {
            System.out.println(Message.MENU);
            choice = inputChoice(sc);

            // a rule broken below (a duplicate code...) arrives here as a message
            try {
                // one case per option: read and validate, then ONE call to the controller
                switch (choice) {
                    // option 1: read a new doctor, then add it
                    case Constants.MENU_ADD:
                        requestDTO = inputAdd(sc);
                        controller.addDoctor(requestDTO);
                        break;

                    // option 2: read a text, then list the doctors whose name contains it
                    case Constants.MENU_SEARCH:
                        requestDTO = inputSearch(sc);
                        controller.searchDoctor(requestDTO);
                        break;

                    // option 3: leave the loop
                    case Constants.MENU_EXIT:
                        running = false;
                        System.out.println(Message.GOODBYE);
                        break;

                    // unreachable: inputChoice only returns a legal option
                    default:
                        break;
                }
            } catch (Exception e) {
                // the sentence was written in Message and thrown by the service
                System.out.println(e.getMessage());
            }
        }
    }

    // Asks for a menu choice until the user types a legal option.
    private static int inputChoice(Scanner sc) {
        String line = "";

        // keep asking until Validation accepts the line
        while (true) {
            System.out.print(Message.INPUT_CHOICE);
            line = sc.nextLine();

            // a wrong line prints the reason and loops again
            try {
                return Validation.getChoice(line, Constants.MENU_ADD, Constants.MENU_EXIT);
            } catch (Exception e) {
                // "You must input a digit." or "Please choose from 1 to 3."
                System.out.println(e.getMessage());
            }
        }
    }

    // Asks one question until the answer is not empty.
    private static String inputText(Scanner sc, String prompt) {
        String line = "";

        // keep asking until the text is not empty
        while (true) {
            System.out.print(prompt);
            line = sc.nextLine();

            // an empty line prints "This field is required." and loops again
            try {
                return Validation.getNonEmpty(line);
            } catch (Exception e) {
                // show why the line was refused
                System.out.println(e.getMessage());
            }
        }
    }

    // Reads the three fields of a new doctor into a request.
    private static DoctorRequestDTO inputAdd(Scanner sc) {
        DoctorRequestDTO requestDTO = new DoctorRequestDTO();

        requestDTO.setCode(inputText(sc, Message.INPUT_CODE));
        requestDTO.setName(inputText(sc, Message.INPUT_NAME));
        requestDTO.setSpecialization(inputText(sc, Message.INPUT_SPECIALIZATION));
        return requestDTO;
    }

    // Reads the search text into a request.
    private static DoctorRequestDTO inputSearch(Scanner sc) {
        DoctorRequestDTO requestDTO = new DoctorRequestDTO();

        requestDTO.setSearchText(inputText(sc, Message.INPUT_SEARCH));
        return requestDTO;
    }
}
